    match (section, key) {
        (Section::Root, b"schema_version") => {
            builder.mark(1 << 0)?;
            builder.schema_version = parse_u64(value)?;
        }
        (Section::Instance, b"id") => {
            builder.mark(1 << 1)?;
            builder.id = parse_string(value)?;
        }
        (Section::Instance, b"root") => {
