            builder.access_gid = parse_u64(value)?;
        }
        (Section::Hooks, b"pre_boot") => {
            builder.mark(1u128 << 32)?;
            builder.pre_boot_hooks = parse_list(value)?;
        }
        (Section::Hooks, b"timeout_seconds") => {
            builder.mark(1u128 << 33)?;
